import { describe, it, expect, vi } from "vitest";
import { fireEvent, render, screen } from "src/utils/test-utils";
import BulkActionsBar from "../BulkActionsBar";

describe("BulkActionsBar", () => {
  const defaultProps = {
    selectedCount: 3,
    onClearSelection: vi.fn(),
    onAction: vi.fn(),
    isSimulator: false,
  };

  it("renders nothing when selectedCount is 0", () => {
    const { container } = render(
      <BulkActionsBar {...defaultProps} selectedCount={0} />,
    );
    expect(container.firstChild).toBeNull();
  });

  it("renders selection count", () => {
    render(<BulkActionsBar {...defaultProps} />);
    expect(screen.getByText("3 selected")).toBeInTheDocument();
  });

  it("renders filter-mode label when allMatching is true", () => {
    render(
      <BulkActionsBar {...defaultProps} selectedCount={700} allMatching />,
    );
    expect(screen.getByText("All 700 matching filter")).toBeInTheDocument();
    expect(screen.queryByText("700 selected")).not.toBeInTheDocument();
  });

  it("labels lower-bound filter selections without claiming an exact total", () => {
    render(
      <BulkActionsBar
        {...defaultProps}
        selectedCount={26}
        selectedCountIsLowerBound
        allMatching
      />,
    );
    expect(screen.getByText("All matching filter (≥26)")).toBeInTheDocument();
    expect(
      screen.queryByText("All 26 matching filter"),
    ).not.toBeInTheDocument();
  });

  it("does not expose single-row actions for a lower-bound count of one", async () => {
    render(
      <BulkActionsBar
        {...defaultProps}
        selectedCount={1}
        selectedCountIsLowerBound
      />,
    );
    fireEvent.click(screen.getByText("Actions"));
    await screen.findByText("Move to dataset");
    expect(screen.queryByText("Annotate")).not.toBeInTheDocument();
  });

  it("renders Actions button", () => {
    render(<BulkActionsBar {...defaultProps} />);
    expect(screen.getByText("Actions")).toBeInTheDocument();
  });

  it("renders clear (×) button", () => {
    render(<BulkActionsBar {...defaultProps} />);
    // The × button is an IconButton — find it by its position
    const buttons = screen.getAllByRole("button");
    // Should have Actions button + × button
    expect(buttons.length).toBeGreaterThanOrEqual(2);
  });

  it("calls onClearSelection when × is clicked", () => {
    const onClear = vi.fn();
    render(<BulkActionsBar {...defaultProps} onClearSelection={onClear} />);
    // Last button is the × clear button
    const buttons = screen.getAllByRole("button");
    const clearButton = buttons[buttons.length - 1];
    clearButton.click();
    expect(onClear).toHaveBeenCalledTimes(1);
  });

  it("opens dropdown menu when Actions is clicked", async () => {
    render(<BulkActionsBar {...defaultProps} />);
    screen.getByText("Actions").click();
    // Menu items should appear (via MUI Menu portal)
    expect(await screen.findByText("Move to dataset")).toBeInTheDocument();
    expect(screen.getByText("Add tags")).toBeInTheDocument();
    expect(screen.getByText("Add to annotation queue")).toBeInTheDocument();
  });

  it("hides Annotate when more than one row is selected", async () => {
    render(<BulkActionsBar {...defaultProps} selectedCount={3} />);
    screen.getByText("Actions").click();
    await screen.findByText("Move to dataset");
    expect(screen.queryByText("Annotate")).not.toBeInTheDocument();
  });

  it("shows Annotate when exactly one row is selected", async () => {
    render(<BulkActionsBar {...defaultProps} selectedCount={1} />);
    screen.getByText("Actions").click();
    expect(await screen.findByText("Annotate")).toBeInTheDocument();
  });

  it("calls onAction with action id when menu item is clicked", async () => {
    const onAction = vi.fn();
    render(<BulkActionsBar {...defaultProps} onAction={onAction} />);
    screen.getByText("Actions").click();
    const menuItem = await screen.findByText("Move to dataset");
    menuItem.click();
    expect(onAction).toHaveBeenCalledWith("dataset", expect.any(Object));
  });

  it("keeps disabled actions visible without firing them", async () => {
    const onAction = vi.fn();
    render(
      <BulkActionsBar
        {...defaultProps}
        onAction={onAction}
        actions={[
          {
            id: "annotation-queue",
            label: "Add to annotation queue",
            icon: "mdi:clipboard-list-outline",
            disabled: true,
            disabledReason: "Selected calls are still in progress.",
          },
        ]}
      />,
    );

    screen.getByText("Actions").click();
    const menuItem = await screen.findByRole("menuitem", {
      name: "Add to annotation queue",
    });

    expect(menuItem).toHaveAttribute("aria-disabled", "true");
    menuItem.click();
    expect(onAction).not.toHaveBeenCalled();
  });
});

import { describe, it, expect } from "vitest";
import {
  isValidNumericInput,
  isCompleteNumericValue,
} from "../TraceFilterPanel";

describe("isValidNumericInput (TH-5195)", () => {
  it("accepts empty / null / undefined as valid (typing-intermediate)", () => {
    expect(isValidNumericInput("")).toBe(true);
    expect(isValidNumericInput(null)).toBe(true);
    expect(isValidNumericInput(undefined)).toBe(true);
  });

  it("accepts integers, decimals, and negatives", () => {
    expect(isValidNumericInput("0")).toBe(true);
    expect(isValidNumericInput("42")).toBe(true);
    expect(isValidNumericInput("1.5")).toBe(true);
    expect(isValidNumericInput("-7")).toBe(true);
    expect(isValidNumericInput("-3.14")).toBe(true);
  });

  it("accepts partial typing states so the user isn't blocked mid-input", () => {
    expect(isValidNumericInput("-")).toBe(true);
    expect(isValidNumericInput(".")).toBe(true);
    expect(isValidNumericInput("-.")).toBe(true);
    expect(isValidNumericInput("1.")).toBe(true);
  });

  it("rejects letters, mixed input, and malformed numbers", () => {
    expect(isValidNumericInput("abc")).toBe(false);
    expect(isValidNumericInput("1.5abc")).toBe(false);
    expect(isValidNumericInput("1.5.6")).toBe(false);
    expect(isValidNumericInput("--1")).toBe(false);
  });

  it("trims surrounding whitespace so the error state matches the Apply gate", () => {
    expect(isValidNumericInput(" 1")).toBe(true);
    expect(isValidNumericInput(" 1.5 ")).toBe(true);
    expect(isValidNumericInput(" ")).toBe(true);
    expect(isValidNumericInput(" 1.5abc ")).toBe(false);
  });

  it("rejects scientific notation (backend filter parser doesn't accept it)", () => {
    expect(isValidNumericInput("1e3")).toBe(false);
    expect(isValidNumericInput("2E-2")).toBe(false);
  });
});

describe("isCompleteNumericValue (TH-5195)", () => {
  it("treats empty / null / undefined as valid because handleApply drops empty rows", () => {
    expect(isCompleteNumericValue("")).toBe(true);
    expect(isCompleteNumericValue(null)).toBe(true);
    expect(isCompleteNumericValue(undefined)).toBe(true);
  });

  it("accepts complete integers, decimals, and negatives", () => {
    expect(isCompleteNumericValue("0")).toBe(true);
    expect(isCompleteNumericValue("42")).toBe(true);
    expect(isCompleteNumericValue("1.5")).toBe(true);
    expect(isCompleteNumericValue(".5")).toBe(true);
    expect(isCompleteNumericValue("-7")).toBe(true);
    expect(isCompleteNumericValue("-.5")).toBe(true);
  });

  it("rejects typing-intermediate states that would NaN at apply", () => {
    expect(isCompleteNumericValue("-")).toBe(false);
    expect(isCompleteNumericValue(".")).toBe(false);
    expect(isCompleteNumericValue("-.")).toBe(false);
  });

  it("rejects letters, mixed input, and malformed numbers", () => {
    expect(isCompleteNumericValue("abc")).toBe(false);
    expect(isCompleteNumericValue("1.5abc")).toBe(false);
    expect(isCompleteNumericValue("1.5.6")).toBe(false);
    expect(isCompleteNumericValue("--1")).toBe(false);
  });

  it("rejects scientific notation (matches isValidNumericInput contract)", () => {
    expect(isCompleteNumericValue("1e3")).toBe(false);
    expect(isCompleteNumericValue("2E-2")).toBe(false);
  });

  it("trims surrounding whitespace before validating", () => {
    expect(isCompleteNumericValue(" 1.5 ")).toBe(true);
    expect(isCompleteNumericValue("  -3 ")).toBe(true);
  });

  it("treats whitespace-only like empty (agrees with isValidNumericInput)", () => {
    expect(isCompleteNumericValue(" ")).toBe(true);
  });
});

package redisstate

import (
	"os"
	"testing"
	"time"
)

// ---------------------------------------------------------------------------
// Mock local limiter for unit tests
// ---------------------------------------------------------------------------

type mockLocalLimiter struct {
	calls    int
	allowed  bool
	remain   int
	resetSec int
}

func (m *mockLocalLimiter) Allow(key string, limit int) (bool, int, int) {
	m.calls++
	return m.allowed, m.remain, m.resetSec
}

func (m *mockLocalLimiter) Stop() {}

// ---------------------------------------------------------------------------
// Unit tests (no Redis)
// ---------------------------------------------------------------------------

func TestRateLimiter_NilClient_FallsBackToLocal(t *testing.T) {
	local := &mockLocalLimiter{allowed: true, remain: 9, resetSec: 55}
	rl := NewRateLimiter(nil, local, "test:rl:")

	allowed, remaining, reset := rl.Allow("key1", 10)
	if !allowed {
		t.Fatal("expected allowed from local fallback")
	}
	if remaining != 9 {
		t.Errorf("remaining = %d, want 9", remaining)
	}
	if reset != 55 {
		t.Errorf("reset = %d, want 55", reset)
	}
	if local.calls != 1 {
		t.Errorf("local.calls = %d, want 1", local.calls)
	}
}

func TestRateLimiter_UnavailableClient_FallsBackToLocal(t *testing.T) {
	// Create a client with a circuit breaker that's already open.
	client := &Client{
		breaker: newCircuitBreaker(1, 10*time.Second),
	}
	client.breaker.recordFailure() // open the circuit

	local := &mockLocalLimiter{allowed: false, remain: 0, resetSec: 30}
	rl := NewRateLimiter(client, local, "test:rl:")

	allowed, remaining, reset := rl.Allow("key1", 10)
	if allowed {
		t.Fatal("expected rejected from local fallback")
	}
	if remaining != 0 {
		t.Errorf("remaining = %d, want 0", remaining)
	}
	if reset != 30 {
		t.Errorf("reset = %d, want 30", reset)
	}
	if local.calls != 1 {
		t.Errorf("local.calls = %d, want 1", local.calls)
	}
}

func TestRateLimiter_Stop_StopsLocal(t *testing.T) {
	local := &mockLocalLimiter{}
	rl := NewRateLimiter(nil, local, "")
	rl.Stop() // Should not panic.
}

// ---------------------------------------------------------------------------
// Integration tests (require real Redis)
// ---------------------------------------------------------------------------

func redisAddr() string {
	addr := os.Getenv("TEST_REDIS_ADDR")
	if addr == "" {
		addr = "localhost:6379"
	}
	return addr
}

func skipIfNoRedis(t *testing.T) *Client {
	t.Helper()
	client, err := NewClient(Config{
		Address: redisAddr(),
		Timeout: 1 * time.Second,
	})
	if err != nil {
		t.Skipf("skipping: Redis not available at %s: %v", redisAddr(), err)
	}
	return client
}

func TestRateLimiter_Redis_AllowUnderLimit(t *testing.T) {
	client := skipIfNoRedis(t)
	defer client.Close()

	ts := time.Now().Format("150405.000")
	local := &mockLocalLimiter{allowed: true, remain: 99, resetSec: 60}
	rl := NewRateLimiter(client, local, "test:rl:allow:"+ts+":")

	limit := 10
	key := "test-allow-key-" + ts
	for i := 0; i < limit; i++ {
		allowed, remaining, reset := rl.Allow(key, limit)
		if !allowed {
			t.Fatalf("request %d: expected allowed", i+1)
		}
		wantRemaining := limit - (i + 1)
		if remaining != wantRemaining {
			t.Errorf("request %d: remaining = %d, want %d", i+1, remaining, wantRemaining)
		}
		if reset < 1 {
			t.Errorf("request %d: reset = %d, want >= 1", i+1, reset)
		}
	}

	// Local should NOT have been called (Redis was available).
	if local.calls != 0 {
		t.Errorf("local.calls = %d, want 0 (Redis handled all)", local.calls)
	}
}

func TestRateLimiter_Redis_RejectsOverLimit(t *testing.T) {
	client := skipIfNoRedis(t)
	defer client.Close()

	local := &mockLocalLimiter{allowed: true, remain: 99, resetSec: 60}
	rl := NewRateLimiter(client, local, "test:rl:reject:")

	limit := 3
	// Use a unique key to avoid collisions with other test runs.
	key := "test-reject-key-" + time.Now().Format("150405.000")

	// Exhaust the limit.
	for i := 0; i < limit; i++ {
		allowed, _, _ := rl.Allow(key, limit)
		if !allowed {
			t.Fatalf("request %d: expected allowed within limit", i+1)
		}
	}

	// Next request should be rejected.
	allowed, remaining, reset := rl.Allow(key, limit)
	if allowed {
		t.Fatal("expected rejected over limit")
	}
	if remaining != 0 {
		t.Errorf("remaining = %d, want 0", remaining)
	}
	if reset < 1 {
		t.Errorf("reset = %d, want >= 1", reset)
	}

	// Local should NOT have been called.
	if local.calls != 0 {
		t.Errorf("local.calls = %d, want 0", local.calls)
	}
}

func TestRateLimiter_Redis_IndependentKeys(t *testing.T) {
	client := skipIfNoRedis(t)
	defer client.Close()

	local := &mockLocalLimiter{allowed: true, remain: 99, resetSec: 60}
	rl := NewRateLimiter(client, local, "test:rl:indep:")

	ts := time.Now().Format("150405.000")
	keyA := "indep-a-" + ts
	keyB := "indep-b-" + ts
	limit := 2

	// Exhaust key A.
	for i := 0; i < limit; i++ {
		rl.Allow(keyA, limit)
	}
	allowed, _, _ := rl.Allow(keyA, limit)
	if allowed {
		t.Fatal("key-a should be rejected")
	}

	// Key B should still be allowed.
	allowed, remaining, _ := rl.Allow(keyB, limit)
	if !allowed {
		t.Fatal("key-b should be allowed (independent)")
	}
	if remaining != limit-1 {
		t.Errorf("key-b remaining = %d, want %d", remaining, limit-1)
	}
}

